    <!-- 返回顶部按钮 -->
    <div class="back-to-top" id="backToTop"></div>

    <script>
        // 页面加载完成后执行
        document.addEventListener('DOMContentLoaded', function() {
            const textContainer = document.getElementById('textContainer');
            const manualOverlay = document.getElementById('manualOverlay');
            const manualClose = document.getElementById('manualClose');
            const bgText = document.getElementById('bgText');
            const textLayer = document.getElementById('textLayer');

            // 设置背景文本随机变化效果
            const words = ['修真者系统', '属性分配', '探索地图', '修炼之路'];
            let currentIndex = 0;

            setInterval(() => {
                currentIndex = (currentIndex + 1) % words.length;
                bgText.style.opacity = 0;

                setTimeout(() => {
                    bgText.textContent = words[currentIndex];
                    bgText.style.opacity = 1;
                }, 500);
            }, 5000);

            // 点击文本容器显示使用说明
            textContainer.addEventListener('click', function() {
                manualOverlay.style.display = 'flex';

                // 添加进入动画
                manualOverlay.style.opacity = 0;
                setTimeout(() => {
                    manualOverlay.style.opacity = 1;
                }, 10);
            });

            // 点击关闭按钮隐藏使用说明
            manualClose.addEventListener('click', function(e) {
                e.stopPropagation();
                manualOverlay.style.opacity = 0;

                setTimeout(() => {
                    manualOverlay.style.display = 'none';
                }, 300);
            });

            // 故障效果
            function createGlitchEffect() {
                const glitchEffect = document.querySelector('.glitch-effect');

                setInterval(() => {
                    if (Math.random() > 0.95) {
                        glitchEffect.style.opacity = 0.1;
                        glitchEffect.style.backgroundPosition = `${Math.random() * 100}% ${Math.random() * 100}%`;
                        glitchEffect.style.filter = `hue-rotate(${Math.random() * 360}deg)`;

                        setTimeout(() => {
                            glitchEffect.style.opacity = 0;
                        }, 50 + Math.random() * 100);
                    }
                }, 200);
            }

            // 文本打字效果
            function typeText(element, text, speed) {
                let i = 0;
                element.textContent = '';

                function typing() {
                    if (i < text.length) {
                        element.textContent += text.charAt(i);
                        i++;
                        setTimeout(typing, speed);
                    }
                }

                typing();
            }

            // 初始化
            createGlitchEffect();

            // 鼠标悬停效果
            textContainer.addEventListener('mousemove', function(e) {
                const x = e.clientX / window.innerWidth;
                const y = e.clientY / window.innerHeight;

                // 文本层跟随鼠标轻微移动
                textLayer.style.transform = `translate(${(x - 0.5) * 20}px, ${(y - 0.5) * 20}px)`;

                // 背景也有轻微的视差效果
                bgText.style.transform = `translate(${(x - 0.5) * -30}px, ${(y - 0.5) * -30}px)`;
            });

            // 初始打字效果
            setTimeout(() => {
                typeText(textLayer, '点击查看使用说明', 100);
            }, 1000);

            // 高亮文本效果
            const highlightElements = document.querySelectorAll('.highlight-text');
            highlightElements.forEach(element => {
                element.addEventListener('mouseenter', function() {
                    this.style.transform = 'translateX(5px)';
                });

                element.addEventListener('mouseleave', function() {
                    this.style.transform = 'translateX(0)';
                });
            });

            // 返回顶部按钮功能
            const backToTopButton = document.getElementById('backToTop');
            const manualContainer = document.querySelector('.manual-container');

            manualContainer.addEventListener('scroll', function() {
                if (this.scrollTop > 300) {
                    backToTopButton.classList.add('visible');
                } else {
                    backToTopButton.classList.remove('visible');
                }
            });

            backToTopButton.addEventListener('click', function() {
                manualContainer.scrollTo({
                    top: 0,
                    behavior: 'smooth'
                });
            });

            // 内容淡入效果
            function fadeInContent() {
                const contentElements = document.querySelectorAll('.manual-content p, .manual-content h3, .manual-content img');
                contentElements.forEach((element, index) => {
                    element.style.opacity = '0';
                    element.style.transform = 'translateY(20px)';
                    element.style.transition = 'opacity 0.5s ease, transform 0.5s ease';

                    setTimeout(() => {
                        element.style.opacity = '1';
                        element.style.transform = 'translateY(0)';
                    }, 100 + index * 80);
                });
            }

            // 打开指南时触发动画
            textContainer.addEventListener('click', function() {
                setTimeout(fadeInContent, 300);
            });
        });
    </script>
</body>
</html>

