            transform: scale(0.98);
        }

        .page-button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
            transform: none;
        }

        /* 属性点显示 */
        .points-display {
            background: rgba(237,228,201,0.6);
            padding: 10px;
            border-radius: 8px;
            text-align: center;
            margin-bottom: 15px;
            border: 1px solid rgba(161,136,127,0.3);
        }

        .points-value {
            font-size: 20px;
            color: #8b4513;
            font-weight: bold;
        }

        /* 选择框通用样式 */
        .section-title {
            color: #4E342E;
            border-bottom: 1px solid #a1887f;
            padding-bottom: 6px;
            margin: 15px 0 10px;
            font-size: 16px;
        }

        .race-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 10px;
            margin-bottom: 15px;
        }

        .race-item {
            border: 1px solid #a1887f;
            border-radius: 8px;
            background: rgba(237,228,201,0.4);
            padding: 12px;
            transition: all 0.3s ease;
            cursor: pointer;
            touch-action: manipulation;
        }

        .race-item:active {
            transform: scale(0.98);
        }

        .race-item.active {
            background: rgba(161,136,127,0.2);
            box-shadow: 0 0 8px rgba(78,52,46,0.3);
        }

        .race-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 8px;
            flex-wrap: wrap;
            gap: 5px;
        }

        .race-name {
            font-size: 16px;
            color: #4E342E;
            font-weight: bold;
            flex: 1;
        }

        .race-bonus {
            background-color: #a1887f;
            color: white;
            padding: 2px 6px;
            border-radius: 12px;
            font-size: 12px;
            white-space: nowrap;
        }

        .race-desc {
            color: #5C4033;
            line-height: 1.4;
            font-size: 14px;
        }

        .select-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
            gap: 8px;
            margin-bottom: 15px;
        }

        .select-button {
            padding: 8px 5px;
            background: rgba(237,228,201,0.4);
            border: 1px solid #a1887f;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.3s ease;
            text-align: center;
            font-family: inherit;
            color: #5C4033;
            font-size: 14px;
            touch-action: manipulation;
        }

        .select-button:active {
            transform: scale(0.95);
        }

        .select-button.active {
            background: rgba(161,136,127,0.5);
            color: #fff;
            box-shadow: 0 0 6px rgba(78,52,46,0.3);
        }

        /* 镇魔司按钮 */
        .zmb-button {
            width: 100%;
            padding: 12px;
            margin-bottom: 10px;
            background: rgba(161,136,127,0.2);
            border: 1px solid #a1887f;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.3s ease;
            text-align: center;
            font-family: inherit;
            color: #5C4033;
            font-size: 14px;
            touch-action: manipulation;
        }

        .zmb-button:active {
            transform: scale(0.98);
        }

        .zmb-button.active {
            background: rgba(161,136,127,0.6);
            color: #fff;
            box-shadow: 0 0 6px rgba(78,52,46,0.3);
        }

        /* 属性按钮组 */
        .attr-groups {
            display: grid;
            grid-template-columns: 1fr;
            gap: 10px;
            margin-bottom: 15px;
        }

        .attr-group {
            border: 1px solid rgba(161,136,127,0.3);
            border-radius: 8px;
            padding: 10px;
            background: rgba(237,228,201,0.3);
        }

        .attr-title {
            text-align: center;
            font-size: 16px;
            color: #5C4033;
            margin-bottom: 8px;
            font-weight: bold;
            border-bottom: 1px dashed rgba(161,136,127,0.3);
            padding-bottom: 5px;
        }

        .attr-buttons {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 6px;
        }

        .attr-button {
            padding: 10px 0;
            background: linear-gradient(135deg,#d4c0a8,#c0a88c);
            border: 1px solid #a1887f;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.3s ease;
            text-align: center;
            font-family: inherit;
            color: #4E342E;
            font-size: 14px;
            touch-action: manipulation;
        }

        .attr-button.x5 {
            background: linear-gradient(135deg, #c0a88c, #b0987c);
            color: #3a2a1e;
        }

        .attr-button.x10 {
            background: linear-gradient(135deg, #b0987c, #9a826c);
            color: #fff;
        }

        .attr-button:active:not(:disabled) {
            transform: scale(0.95);
        }

        .attr-button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        /* 文本区域和按钮 */
        .text-area {
            width: 100%;
            height: 120px;
            border: 1px solid #a1887f;
            border-radius: 8px;
            padding: 10px;
            background: rgba(237,228,201,0.4);
            color: #5C4033;
            resize: vertical;
            font-family: inherit;
            box-sizing: border-box;
            margin-bottom: 10px;
            line-height: 1.5;
            font-size: 14px;
            -webkit-appearance: none;
        }

        .button-row {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 8px;
            margin-bottom: 15px;
        }

        .control-button {
            padding: 10px 5px;
            background: linear-gradient(135deg,#d4c0a8,#c0a88c);
            border: 1px solid #a1887f;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.2s ease;
            font-family: inherit;
            color: #4E342E;
            font-size: 14px;
            touch-action: manipulation;
        }

        .control-button:active {
            background: linear-gradient(135deg, #c0a88c, #b0987c);
            transform: scale(0.95);
        }

        /* 通知提示 */
        .notification {
            position: fixed;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            background: #4E342E;
            color: #f5efdc;
            padding: 10px 20px;
            border-radius: 8px;
            box-shadow: 0 3px 10px rgba(0,0,0,0.2);
            z-index: 100;
            opacity: 0;
            transition: opacity 0.3s ease;
            pointer-events: none;
            max-width: 90%;
            font-size: 14px;
            text-align: center;
        }

        .notification.show {
            opacity: 1;
        }

        /* 进度指示器 */
        .progress-dots {
            display: flex;
            justify-content: center;
            margin-bottom: 15px;
            gap: 8px;
        }

        .progress-dot {
            width: 10px;
            height: 10px;
            background-color: rgba(161,136,127,0.3);
            border-radius: 50%;
            transition: all 0.3s ease;
        }

        .progress-dot.active {
            background-color: #a1887f;
            transform: scale(1.3);
        }

        /* 平板适配 */
        @media (min-width: 600px) {
            .container {
                padding: 20px;
            }

            .header h1 {
                font-size: 28px;
            }

            .points-value {
                font-size: 24px;
            }

            .attr-groups {
                grid-template-columns: repeat(2, 1fr);
                gap: 15px;
            }

            .text-area {
                height: 150px;
            }

            .race-name {
                font-size: 18px;
            }

            .race-desc {
                font-size: 15px;
            }
        }

        /* 大屏适配 */
        @media (min-width: 768px) {
            body {
                padding: 20px;
            }

            .container {
                padding: 25px;
            }

            .text-area {
                height: 180px;
            }

            .select-grid {
                grid-template-columns: repeat(3, 1fr);
            }
        }

        /* 防止横屏时内容过宽 */
        @media (orientation: landscape) and (max-height: 500px) {
            .container {
                max-height: 90vh;
                overflow-y: auto;
            }

            .text-area {
                height: 100px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- 标题 -->
        <div class="header">
            <h1>修真者属性配置</h1>
        </div>

        <!-- 进度指示器 -->
        <div class="progress-dots">
            <div class="progress-dot dot-1 active"></div>
            <div class="progress-dot dot-2"></div>
            <div class="progress-dot dot-3"></div>
        </div>

        <!-- 页面1: 种族选择 -->
        <div id="page-1" class="page active">
            <div class="section-title">选择种族</div>

            <!-- 属性点显示 -->
            <div class="points-display">
                <span>种族加成属性点：</span>
                <span id="race-bonus" class="points-value">0</span>
                <div style="font-size: 12px; margin-top: 5px;">
                    （固定加成，不随境界变化）
                </div>
            </div>

            <div class="race-grid">
                <div class="race-item active" data-race="人类" data-bonus="0">
                    <div class="race-header">
                        <div class="race-name">人类</div>
                        <div class="race-bonus">+0点</div>
                    </div>
                    <div class="race-desc">
                        普通人类，不具有种族特殊能力，但适应力强，拥有无限潜力。
                    </div>
                </div>

                <div class="race-item" data-race="半魔" data-bonus="1">
                    <div class="race-header">
                        <div class="race-name">半魔</div>
                        <div class="race-bonus">+1点</div>
                    </div>
                    <div class="race-desc">
                        人类与妖魔结合的后裔，兼具两族特性，拥有一定的妖魔血脉能力，但也承受着血脉带来的排斥与痛苦。
                    </div>
                </div>

                <div class="race-item" data-race="不定形之祟" data-bonus="3">
                    <div class="race-header">
                        <div class="race-name">不定形之祟（低等妖魔）</div>
                        <div class="race-bonus">+3点</div>
                    </div>
                    <div class="race-desc">
                        无固定形态，常依附于概念、情绪或负面能量（如怨念、诅咒、噩梦）。隐匿性强，手段诡秘，难以防范。常见于各类传说中的鬼、灵、祟。
                    </div>
                </div>

                <div class="race-item" data-race="血肉畸魔" data-bonus="3">
                    <div class="race-header">
                        <div class="race-name">血肉畸魔（低等妖魔）</div>
                        <div class="race-bonus">+3点</div>
                    </div>
                    <div class="race-desc">
                        由大量腐烂血肉、亡者尸骸及浓烈死怨聚合而成的恐怖存在。形态极度扭曲可怖，散发着强烈的腐臭与憎恨，常具备吞噬血肉、散播瘟疫或操控尸骸的能力。
                    </div>
                </div>

                <div class="race-item" data-race="异化之躯" data-bonus="5">
                    <div class="race-header">
                        <div class="race-name">异化之躯（中等妖魔）</div>
                        <div class="race-bonus">+5点</div>
                    </div>
                    <div class="race-desc">
                        拥有物理形态，但躯体扭曲、畸变或多种生物特征杂糅。来源于受魔气侵染的动植物、污秽之地诞生的魔物、失去神性庇护而堕落的神话生物后裔，或由凡人通过禁忌仪式/力量反噬转化而成。力量多源于其异化的肉体和原始本能。
                    </div>
                </div>

                <div class="race-item" data-race="星空来者" data-bonus="8">
                    <div class="race-header">
                        <div class="race-name">星空来者</div>
                        <div class="race-bonus">+8点</div>
                    </div>
                    <div class="race-desc">
                        来自星空彼岸，非此界原生的异界邪魔。因世界失去神明庇护，屏障削弱，从而得以降临并肆虐。形态与能力可能完全迥异于本土妖魔，常带来未知的恐惧与毁灭。形态各异（克苏鲁风格居多）。
                    </div>
                </div>

                <div class="race-item" data-race="亚龙" data-bonus="10">
                    <div class="race-header">
                        <div class="race-name">亚龙（特殊高等族裔）</div>
                        <div class="race-bonus">+10点</div>
                    </div>
                    <div class="race-desc">
                        源自东西方各类真龙，但因血脉不纯或堕落腐化，失去了部分神圣特性，却获得了妖魔的狡诈与凶残。天生拥有远超同级妖魔的强悍肉体，以及威力惊人的多样天赋神通。所有亚龙皆具备飞行、化为类人形态、以及吐息攻击（吐息种类因个体而异）的能力。既能维持部分龙类特征的类人形态（展现智慧与诡诈），亦能显化狰狞的巨兽原形（释放毁灭力量）。
                    </div>
                </div>
            </div>

            <div class="page-nav">
                <button class="page-button page-prev" disabled>上一步</button>
                <button class="page-button page-next">下一步</button>
            </div>
        </div>

        <!-- 页面2: 境界选择 -->
        <div id="page-2" class="page">
            <!-- 属性点显示 -->
            <div class="points-display">
                <span>可用属性点：</span>
                <span id="attribute-points" class="points-value">10</span>
                <div style="font-size: 12px; margin-top: 5px;">
                    （境界基础点 + 种族加成点）
                </div>
            </div>

            <!-- 隶属镇魔司按钮 -->
            <button id="zmb-button" class="zmb-button">隶属镇魔司</button>

            <div class="section-title">选择境界</div>
            <div class="select-grid" id="realm-grid">
                <button class="select-button active" data-realm="锻体" data-points="10" data-title="巡城卒">锻体</button>
                <button class="select-button" data-realm="皮关" data-points="25" data-title="镇魔吏">皮关</button>
                <button class="select-button" data-realm="淬骨" data-points="40" data-title="荡寇卫">淬骨</button>
                <button class="select-button" data-realm="奔马" data-points="55" data-title="讨逆校尉">奔马</button>
                <button class="select-button" data-realm="狩虎" data-points="70" data-title="伏妖都尉">狩虎</button>
                <button class="select-button" data-realm="豫象" data-points="85" data-title="破煞将军">豫象</button>
                <button class="select-button" data-realm="凝气" data-points="100" data-title="镇灵使">凝气</button>
                <button class="select-button" data-realm="腾龙" data-points="115" data-title="巡天真人">腾龙</button>
                <button class="select-button" data-realm="破虚" data-points="130" data-title="镇国司主">破虚</button>
            </div>

            <div class="page-nav">
                <button class="page-button page-prev">上一步</button>
                <button class="page-button page-next">下一步</button>
            </div>
        </div>

        <!-- 页面3: 属性分配 -->
        <div id="page-3" class="page">
            <!-- 属性点显示 -->
            <div class="points-display">
                <span>可用属性点：</span>
                <span id="remaining-points" class="points-value">10</span>
            </div>

            <!-- 属性分配 -->
            <div class="section-title">分配属性点</div>
            <div class="attr-groups">
                <!-- 意属性组 -->
                <div class="attr-group">
                    <div class="attr-title">意</div>
                    <div class="attr-buttons">
                        <button class="attr-button" data-attr="意" data-value="1">+1</button>
                        <button class="attr-button x5" data-attr="意" data-value="5">+5</button>
                        <button class="attr-button x10" data-attr="意" data-value="10">+10</button>
                    </div>
                </div>

                <!-- 敏捷属性组 -->
                <div class="attr-group">
                    <div class="attr-title">敏捷</div>
                    <div class="attr-buttons">
                        <button class="attr-button" data-attr="敏捷" data-value="1">+1</button>
                        <button class="attr-button x5" data-attr="敏捷" data-value="5">+5</button>
                        <button class="attr-button x10" data-attr="敏捷" data-value="10">+10</button>
                    </div>
                </div>

                <!-- AC属性组 -->
                <div class="attr-group">
                    <div class="attr-title">AC</div>
                    <div class="attr-buttons">
                        <button class="attr-button" data-attr="AC" data-value="1">+1</button>
                        <button class="attr-button x5" data-attr="AC" data-value="5">+5</button>
                        <button class="attr-button x10" data-attr="AC" data-value="10">+10</button>
                    </div>
                </div>

                <!-- 体质属性组 -->
                <div class="attr-group">
                    <div class="attr-title">体质</div>
                    <div class="attr-buttons">
                        <button class="attr-button" data-attr="体质" data-value="1">+1</button>
                        <button class="attr-button x5" data-attr="体质" data-value="5">+5</button>
                        <button class="attr-button x10" data-attr="体质" data-value="10">+10</button>
                    </div>
                </div>
            </div>

            <!-- 文本输出 -->
            <div class="section-title">配置结果</div>
            <textarea id="attr-text" class="text-area">人类，锻体境界，不隶属于镇魔司：</textarea>
            <div class="button-row">
                <button id="btn-summarize" class="control-button">统计</button>
                <button id="btn-clear" class="control-button">清空</button>
                <button id="btn-copy" class="control-button">复制</button>
            </div>

            <div class="page-nav">
                <button class="page-button page-prev">上一步</button>
                <button class="page-button page-next" disabled>完成</button>
            </div>
        </div>
    </div>

    <!-- 通知提示 -->
    <div id="notification" class="notification"></div>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            // 初始化变量
            let basePoints = 10;        // 基础点数（基于境界）
            let raceBonus = 0;          // 种族固定加成
            let totalPoints = 10;       // 总可用点数
            let usedPoints = 0;         // 已使用点数
            let currentRealm = '锻体';   // 当前境界
            let currentTitle = '';      // 当前官职
            let currentRace = '人类';    // 当前种族
            let isZMB = false;          // 是否隶属镇魔司
            let currentPage = 1;        // 当前页面
            let attributeHistory = '';  // 🆕 新增：保存属性分配历史

            // 境界对应的基础属性点
            const realmBasePoints = {
                '锻体': 10,
                '皮关': 25,
                '淬骨': 40,
                '奔马': 55,
                '狩虎': 70,
                '豫象': 85,
                '凝气': 100,
                '腾龙': 115,
                '破虚': 130
            };

            // 境界对应的官职
            const realmTitles = {
                '锻体': '巡城卒',
                '皮关': '镇魔吏',
                '淬骨': '荡寇卫',
                '奔马': '讨逆校尉',
                '狩虎': '伏妖都尉',
                '豫象': '破煞将军',
                '凝气': '镇灵使',
                '腾龙': '巡天真人',
                '破虚': '镇国司主'
            };

            // DOM元素引用
            const attributePointsDisplay = document.getElementById('attribute-points');
            const remainingPointsDisplay = document.getElementById('remaining-points');
            const raceBonusDisplay = document.getElementById('race-bonus');
            const attrText = document.getElementById('attr-text');
            const btnSummarize = document.getElementById('btn-summarize');
            const btnClear = document.getElementById('btn-clear');
            const btnCopy = document.getElementById('btn-copy');
            const zmbButton = document.getElementById('zmb-button');
            const notification = document.getElementById('notification');
            const realmButtons = document.querySelectorAll('#realm-grid .select-button');
            const raceItems = document.querySelectorAll('.race-item');
            const attrButtons = document.querySelectorAll('.attr-button');
            const pages = document.querySelectorAll('.page');
            const nextButtons = document.querySelectorAll('.page-next');
            const prevButtons = document.querySelectorAll('.page-prev');
            const progressDots = document.querySelectorAll('.progress-dot');

                 // 更新总属性点
            function updateTotalPoints() {
                totalPoints = basePoints + raceBonus - usedPoints;

                if (attributePointsDisplay) attributePointsDisplay.textContent = basePoints + raceBonus;
                if (remainingPointsDisplay) remainingPointsDisplay.textContent = totalPoints;
                if (raceBonusDisplay) raceBonusDisplay.textContent = raceBonus;

                updateButtonStates();
            }

            // 更新按钮状态
            function updateButtonStates() {
                attrButtons.forEach(btn => {
                    const value = parseInt(btn.dataset.value);
                    if (totalPoints < value) {
                        btn.disabled = true;
                        btn.style.opacity = "0.5";
                        btn.style.cursor = "not-allowed";
                    } else {
                        btn.disabled = false;
                        btn.style.opacity = "1";
                        btn.style.cursor = "pointer";
                    }
                });
            }

            // 显示通知
            function showNotification(message, duration = 2000) {
                notification.textContent = message;
                notification.classList.add('show');
                setTimeout(() => {
                    notification.classList.remove('show');
                }, duration);
            }

            // 🆕 修复后的更新显示文本函数
            function updateDisplayText() {
                // 获取文本框当前内容
                const currentText = attrText.value;
                const lines = currentText.split('\n');

                // 构建新的第一行
                let firstLine;
                if (isZMB) {
                    firstLine = `${currentRace}，${currentRealm}境界，${realmTitles[currentRealm]}：`;
                } else {
                    firstLine = `${currentRace}，${currentRealm}境界，不隶属于镇魔司：`;
                }

                // 如果有属性分配记录，保留它们
                if (lines.length > 1) {
                    lines[0] = firstLine;
                    attrText.value = lines.join('\n');
                } else {
                    attrText.value = firstLine;
                }
            }

            // 🆕 保存属性分配历史
            function saveAttributeHistory() {
                const currentText = attrText.value;
                const lines = currentText.split('\n');
                if (lines.length > 1) {
                    // 保存除第一行外的所有内容
                    attributeHistory = lines.slice(1).join('\n');
                }
            }

            // 🆕 恢复属性分配历史
            function restoreAttributeHistory() {
                if (attributeHistory) {
                    const currentText = attrText.value;
                    const firstLine = currentText.split('\n')[0];
                    attrText.value = firstLine + '\n' + attributeHistory;
                }
            }

            // 添加属性
            function addAttribute(attrName, amount) {
                if (totalPoints >= amount) {
                    attrText.value += `\n${attrName}分配属性点+${amount}，`;
                    totalPoints -= amount;
                    usedPoints += amount;
                    remainingPointsDisplay.textContent = totalPoints;
                    attrText.scrollTop = attrText.scrollHeight;
                    updateButtonStates();

                    // 🆕 保存属性历史
                    saveAttributeHistory();
                } else {
                    showNotification(`属性点不足，无法分配${amount}点`);
                }
            }

            // 切换页面
            function changePage(direction) {
                const newPage = currentPage + direction;
                if (newPage < 1 || newPage > 3) return;

                // 🆕 离开第3页时保存属性历史
                if (currentPage === 3) {
                    saveAttributeHistory();
                }

                // 隐藏当前页，显示新页
                document.getElementById(`page-${currentPage}`).classList.remove('active');
                document.getElementById(`page-${newPage}`).classList.add('active');

                // 更新进度点
                progressDots.forEach(dot => dot.classList.remove('active'));
                document.querySelector(`.dot-${newPage}`).classList.add('active');

                // 更新当前页
                currentPage = newPage;

                // 🆕 进入第3页时恢复属性历史
                if (newPage === 3) {
                    restoreAttributeHistory();
                }
            }

            // 绑定属性按钮点击事件
            attrButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const attrName = this.dataset.attr;
                    const amount = parseInt(this.dataset.value);
                    addAttribute(attrName, amount);
                });
            });

            // 🆕 修复后的镇魔司按钮点击事件
            zmbButton.addEventListener('click', function() {
                // 保存当前属性历史
                saveAttributeHistory();

                isZMB = !isZMB;
                if (isZMB) {
                    zmbButton.classList.add('active');
                    zmbButton.textContent = '隶属镇魔司 ✓';
                } else {
                    zmbButton.classList.remove('active');
                    zmbButton.textContent = '隶属镇魔司';
                }

                // 更新显示文本
                updateDisplayText();

                // 恢复属性历史
                restoreAttributeHistory();
            });

            // 种族选择
            raceItems.forEach(item => {
                item.addEventListener('click', function() {
                    const newRace = this.dataset.race;
                    const newRaceBonus = parseInt(this.dataset.bonus);

                    // 如果已分配点数，确认是否切换
                    if (usedPoints > 0) {
                        if (!confirm(`切换种族将清空已分配的属性点。确定要切换到${newRace}吗？`)) {
                            return;
                        }
                    }

                    // 更新选中状态
                    raceItems.forEach(itm => itm.classList.remove('active'));
                    this.classList.add('active');

                    // 更新当前种族和种族加成
                    currentRace = newRace;
                    raceBonus = newRaceBonus;

                    // 重置属性点
                    usedPoints = 0;
                    attributeHistory = ''; // 🆕 清空属性历史
                    updateTotalPoints();

                    // 更新文本框
                    updateDisplayText();

                    showNotification(`已选择${newRace}，种族加成：+${newRaceBonus}点属性`);
                });
            });

            // 境界选择
            realmButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const newRealm = this.dataset.realm;
                    const newBasePoints = parseInt(this.dataset.points);

                    // 如果已分配点数，确认是否切换
                    if (usedPoints > 0) {
                        if (!confirm(`切换境界将清空已分配的属性点。确定要切换到${newRealm}吗？`)) {
                            return;
                        }
                    }

                    // 更新选中状态
                    realmButtons.forEach(btn => btn.classList.remove('active'));
                    this.classList.add('active');

                    // 更新当前境界
                    currentRealm = newRealm;
                    basePoints = newBasePoints;

                    // 重置属性点
                    usedPoints = 0;
                    attributeHistory = ''; // 🆕 清空属性历史
                    updateTotalPoints();

                    // 更新文本框
                    updateDisplayText();

                    showNotification(`已选择${newRealm}境界，基础属性点：${newBasePoints}点`);
                });
            });

            // 统计按钮
            btnSummarize.addEventListener('click', function() {
                const text = attrText.value;

                if (!text.trim()) {
                    showNotification('没有可统计的内容');
                    return;
                }

                // 提取第一行（包含种族、境界和官职）
                const lines = text.split('\n');
                const firstLine = lines[0] || '';

                // 解析属性点分配
                const attrCounts = {};
                const regex = /(\S+)分配属性点\+(\d+)/g;
                let match;
                let foundMatch = false;

                while ((match = regex.exec(text)) !== null) {
                    foundMatch = true;
                    const attrName = match[1];
                    const value = parseInt(match[2]);
                    attrCounts[attrName] = (attrCounts[attrName] || 0) + value;
                }

                if (!foundMatch) {
                    showNotification('没有找到可统计的属性点分配');
                    return;
                }

                // 构建统计结果，保留首行
                let result = firstLine + '\n';

                // 按照特定顺序显示属性
                const attrOrder = ['体质', '意', 'AC', '敏捷'];

                attrOrder.forEach(attr => {
                    if (attrCounts[attr]) {
                        result += `${attr}分配属性点+${attrCounts[attr]}，\n`;
                    }
                });

                // 处理可能的其他属性
                for (const attr in attrCounts) {
                    if (!attrOrder.includes(attr) && attrCounts[attr] > 0) {
                        result += `${attr}分配属性点+${attrCounts[attr]}，\n`;
                    }
                }

                // 更新文本框
                attrText.value = result;
                attributeHistory = result.split('\n').slice(1).join('\n'); // 🆕 更新属性历史
                showNotification('属性点已成功统计');
            });

            // 清空按钮
            btnClear.addEventListener('click', function() {
                if (usedPoints <= 0) {
                    showNotification('没有已分配的点数可返还');
                    return;
                }

                if (confirm('确定要清空所有已分配的属性点并返还点数吗？')) {
                    // 恢复点数
                    usedPoints = 0;
                    attributeHistory = ''; // 🆕 清空属性历史
                    updateTotalPoints();

                    // 只保留首行信息
                    updateDisplayText();

                    showNotification('已清空并返还属性点');
                }
            });

            // 复制按钮
            btnCopy.addEventListener('click', function() {
                if (!attrText.value.trim()) {
                    showNotification('没有内容可复制');
                    return;
                }

                // 移动端复制方法
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(attrText.value).then(() => {
                        showNotification('已复制到剪贴板');
                    }).catch(() => {
                        fallbackCopy();
                    });
                } else {
                    fallbackCopy();
                }

                function fallbackCopy() {
                    attrText.select();
                    attrText.setSelectionRange(0, 99999); // 移动端兼容
                    try {
                        document.execCommand('copy');
                        showNotification('已复制到剪贴板');
                    } catch (err) {
                        showNotification('复制失败，请手动复制');
                    }
                    window.getSelection().removeAllRanges();
                }
            });

            // 页面导航按钮
            nextButtons.forEach(button => {
                button.addEventListener('click', () => changePage(1));
            });

            prevButtons.forEach(button => {
                button.addEventListener('click', () => changePage(-1));
            });

            // 初始化页面
            updateTotalPoints();
            updateDisplayText(); // 确保默认显示"不隶属于镇魔司"

            // 阻止双击缩放
            let lastTouchEnd = 0;
            document.addEventListener('touchend', function(event) {
                const now = Date.now();
                if (now - lastTouchEnd <= 300) {
                    event.preventDefault();
                }
                lastTouchEnd = now;
            }, false);

            // 阻止捏合缩放
            document.addEventListener('touchstart', function(event) {
                if (event.touches.length > 1) {
                    event.preventDefault();
                }
            }, { passive: false });

            // 优化触摸响应
            const touchElements = document.querySelectorAll('.race-item, .select-button, .attr-button, .control-button, .page-button, .zmb-button');
            touchElements.forEach(element => {
                element.addEventListener('touchstart', function() {
                    this.style.opacity = '0.7';
                }, { passive: true });

                element.addEventListener('touchend', function() {
                    this.style.opacity = '';
                }, { passive: true });

                element.addEventListener('touchcancel', function() {
                    this.style.opacity = '';
                }, { passive: true });
            });
        });
    </script>
</body>
</html>
