    <script>
        // =================== 配置区 ===================
        // 是否启用调试，设置为true将显示调试信息
        const DEBUG = false;

        // =================== 工具函数 ===================
        function debug(message) {
            if (!DEBUG) return;

            console.log(`[Map Debug] ${message}`);

            const panel = document.getElementById('debug-panel');
            if (panel) {
                panel.style.display = 'block';
                const p = document.createElement('p');
                p.textContent = message;
                panel.appendChild(p);
                panel.scrollTop = panel.scrollHeight;
            }
        }

        // =================== 核心函数 ===================
        // 按照参考程序的模式构建命令发送函数
        function sendCommand(message) {
            try {
                // 构建命令数组，与参考程序保持一致
                let commands = [];
                commands.push(`/send ${message}`);
                commands.push('/trigger');
                const commandString = commands.join('|');

                debug(`构建命令: ${commandString}`);

                // 直接调用triggerSlash，与参考程序保持一致
                triggerSlash(commandString);
                debug("命令已发送");
                return true;
            } catch (e) {
                debug(`发送命令出错: ${e.message}`);
                console.error("发送命令出错:", e);

                // 尝试其他方法
                tryAlternativeMethods(message);
                return false;
            }
        }

        // 尝试多种备选方法来发送命令
        function tryAlternativeMethods(message) {
            debug("尝试备选方法发送命令");

            // 这些方法按照从最可能到最不可能的顺序排列
            const methods = [
                // 方法1: 通过window对象
                () => {
                    if (typeof window.triggerSlash === 'function') {
                        window.triggerSlash(`/send ${message}|/trigger`);
                        debug("通过window.triggerSlash发送成功");
                        return true;
                    }
                    return false;
                },

                // 方法2: 通过parent对象 (如果是在iframe中)
                () => {
                    if (window.parent && typeof window.parent.triggerSlash === 'function') {
                        window.parent.triggerSlash(`/send ${message}|/trigger`);
                        debug("通过parent.triggerSlash发送成功");
                        return true;
                    }
                    return false;
                },

                // 方法3: 通过top对象 (更深层次的iframe)
                () => {
                    if (window.top && typeof window.top.triggerSlash === 'function') {
                        window.top.triggerSlash(`/send ${message}|/trigger`);
                        debug("通过top.triggerSlash发送成功");
                        return true;
                    }
                    return false;
                },

                // 方法4: 尝试postMessage方法
                () => {
                    try {
                        window.parent.postMessage({
                            type: 'stt-command',
                            command: `/send ${message}|/trigger`
                        }, '*');
                        debug("通过postMessage发送，结果未知");
                        return true;
                    } catch (e) {
                        return false;
                    }
                }
            ];

            // 尝试每种方法
            for (let method of methods) {
                if (method()) return true;
            }

            debug("所有备选方法均失败");
            return false;
        }

        document.addEventListener('DOMContentLoaded', function () {
            const locationSelectables = document.querySelectorAll('.location-selectable');
            const goToButton = document.getElementById('go-to-selected-btn');
            const tooltip = document.getElementById('copy-tooltip');
            let tooltipTimeout;
            let selectedLocationName = null;
            let selectedLocationElement = null;

            locationSelectables.forEach(item => {
                item.addEventListener('click', function (event) {
                    event.preventDefault(); 

                    // 取消上一个选中的元素
                    if (selectedLocationElement) {
                        selectedLocationElement.classList.remove('selected');
                    }

                    // 选中当前元素
                    this.classList.add('selected');
                    selectedLocationElement = this;
                    selectedLocationName = this.dataset.location;

                    // 激活前往按钮并更新文字
                    goToButton.disabled = false;
                    goToButton.textContent = `前往 ${selectedLocationName}`;
                });
            });

            goToButton.addEventListener('click', function() {
                if (!selectedLocationName) return;

                debug(`开始发送命令，选择的地点是: ${selectedLocationName}`);

                // 使用与参考程序相同的方式构建和发送命令
                const success = sendCommand(`前往 ${selectedLocationName}`); 

                // 显示提示
                tooltip.textContent = success ? 
                    `指令已发送: 前往 ${selectedLocationName}` : 
                    `发送失败，请检查控制台`;

                tooltip.classList.add('show');
                clearTimeout(tooltipTimeout);
                tooltipTimeout = setTimeout(() => {
                    tooltip.classList.remove('show');
                }, 3000);

                // 重置选择
                if (selectedLocationElement) {
                    selectedLocationElement.classList.remove('selected');
                }
                selectedLocationName = null;
                selectedLocationElement = null;
                goToButton.disabled = true;
                goToButton.textContent = '选择一个地点以激活';
            });

            // 添加键盘快捷键
            document.addEventListener('keydown', function(e) {
                // 回车键快速触发"前往"操作
                if (e.key === 'Enter' && !goToButton.disabled) {
                    goToButton.click();
                }
            });

            debug("页面加载完成，地图界面初始化完毕");
        });
    </script>
</body>
</html>
