class BattleSystem {
    static BATTLE_ATTRIBUTES = {
        YI: "意",       // 决定攻击的基础伤害值和暴击额外伤害
        AC: "AC",       // 降低被攻击命中的几率
        CONSTITUTION: "体质",  // 决定最大生命值，1点=20点生命值，默认基础50
        AGILITY: "敏捷"  // 加算到攻击投骰上，影响命中判定
    };

    constructor(gameDataManager) {
        this.gameDataManager = gameDataManager;
    }

    // 生成D20随机数
    rollD20() {
        return Math.floor(Math.random() * 20) + 1; // 1-20
    }

    // 生成指定面数的骰子结果
    rollDice(sides) {
        return Math.floor(Math.random() * sides) + 1; // 1-sides
    }

    // 执行攻击判定
    async performAttack(attackerYi, attackerAgility, defenderAC, skillDamage, defenderHP, skillDescription = "", attacker = "{{user}}", defender = "敌人", specialEffect = "") {
        // 投掷D20判定命中
        const d20Roll = this.rollD20();
        let hitResult = "";
        let damage = 0;
        let isCritical = false;
        let finalHitValue = 0;

        // 判断是否完美命中(D20=20)
        if (d20Roll === 20) {
            hitResult = "完美命中！无视AC直接命中并造成暴击！";
            isCritical = true;
        } else {
            // 计算综合命中值
            finalHitValue = d20Roll + attackerAgility - defenderAC;

            // 判断是否命中(最终命中值>=10)
            if (finalHitValue >= 10) {
                hitResult = "命中！";
            } else {
                hitResult = "未命中！";
            }
        }

        // 只有命中时才计算伤害
        let damageCalculation = "";
        let remainingHP = defenderHP;

        if (hitResult.includes("命中")) {
            // 基础伤害 = 攻击方"意"属性值 + 技能/武器伤害
            damage = attackerYi + skillDamage;
            damageCalculation = `${attackerYi} (意) + ${skillDamage} (技能/武器伤害)`;

            // 如果是暴击，额外增加1D[攻击方当前的"意"值]的伤害
            if (isCritical) {
                const critDamage = this.rollDice(attackerYi);
                damage += critDamage;
                damageCalculation += ` + ${critDamage} (暴击伤害，1D${attackerYi})`;
            }

            // 计算剩余生命值
            remainingHP = Math.max(0, defenderHP - damage);
            damageCalculation += ` = ${damage}点`;
        }

        // 构建技能效果描述
        let effectText = "";
        if (specialEffect && hitResult.includes("命中")) {
            effectText = `触发【${specialEffect}】效果。`;
        }

        // 构建生命值变化描述
        let hpChangeText = "";
        if (hitResult.includes("命中")) {
            hpChangeText = `${defender}当前生命值：${defenderHP}，${defenderHP} - ${damage} = ${remainingHP}。`;
        }

        // 根据不同情况构建最终输出
        let resultText = "";

        if (d20Roll === 20) {
            resultText = `攻击命中：1D20掷出${d20Roll}！${hitResult}${damageCalculation ? "伤害：" + damageCalculation : ""}。${effectText}${hpChangeText}`;
        } else if (hitResult.includes("命中")) {
            resultText = `攻击命中：1D20掷出${d20Roll}。最终命中值：${d20Roll} (骰值) + ${attackerAgility} (攻击方敏捷) - ${defenderAC} (防御方AC) = ${finalHitValue}。${finalHitValue} ≥ 10，${hitResult}${damageCalculation ? "伤害：" + damageCalculation : ""}。${effectText}${hpChangeText}`;
        } else {
            resultText = `攻击命中：1D20掷出${d20Roll}。最终命中值：${d20Roll} (骰值) + ${attackerAgility} (攻击方敏捷) - ${defenderAC} (防御方AC) = ${finalHitValue}。${finalHitValue} < 10，${hitResult}`;
        }

        return {
            d20Roll: d20Roll,
            hitResult: hitResult,
            damage: damage,
            isCritical: isCritical,
            finalHitValue: finalHitValue,
            remainingHP: remainingHP,
            resultText: resultText,
            attacker: attacker,
            defender: defender,
            skillDescription: skillDescription
        };
    }

    // 输出攻击结果到AI
    async outputAttackResult(result) {
        const message = `<投骰>${result.resultText}</投骰>`;
        await triggerSlash(`/send ${message}`);
    }
}

