    .note {
      position: absolute;
      opacity: 0.2;
      width: 10px;
      height: 10px;
      background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%23a1887f"><path d="M12,3V12.26C11.5,12.09 11,12 10.5,12C8.54,12 7,13.54 7,15.5C7,17.46 8.54,19 10.5,19C12.46,19 14,17.46 14,15.5V6H18V3H12Z"/></svg>'); /* Muted brown fill */
      animation: float 8s infinite ease-in;
