    .note:nth-child(1) { left: 10%; top: 20%; animation-duration: 6s; }
    .note:nth-child(2) { left: 85%; top: 30%; animation-duration: 7s; animation-delay: 1s; }
    .note:nth-child(3) { left: 20%; top: 80%; animation-duration: 5s; animation-delay: 0.5s; }
