  <script>
    // 存储原始属性值和已分配点数
    let originalValues = {};
    let attributeIncrements = {
      'constitution': 0,
      'will': 0,
      'ac': 0,
      'agility': 0
    };
    let totalPointsSpent = 0;
    let initialPointsAvailable = 0;

    // 显示标签页
    function showTab(tabId) {
      // 隐藏所有内容
      document.querySelectorAll('.tab-content').forEach(content => {
        content.classList.remove('active');
      });

      // 取消所有按钮的激活状态
      document.querySelectorAll('.tab-button').forEach(button => {
        button.classList.remove('active');
      });

      // 显示选中的内容并激活对应按钮
      document.getElementById('content-' + tabId).classList.add('active');
      document.getElementById('tab-' + tabId).classList.add('active');
    }

    // 分配属性点
    function allocatePoint(attributeType) {
      // 获取当前属性点
      let pointsElement = document.getElementById('attribute-points');
      let availablePoints = parseInt(pointsElement.textContent);

      // 检查是否还有可用点数
      if (availablePoints <= 0) {
        alert('没有可用属性点！');
        return;
      }

      // 获取对应属性值元素
      let valueElement = document.getElementById(attributeType + '-value');
      let currentValue = parseInt(valueElement.textContent);

      // 增加属性值
      valueElement.textContent = currentValue + 1;

      // 更新已分配点数显示
      attributeIncrements[attributeType]++;
      document.getElementById(attributeType + '-increment').textContent = `(+${attributeIncrements[attributeType]})`;

      // 减少可用点数并更新总消耗点数
      availablePoints--;
      totalPointsSpent++;
      pointsElement.textContent = availablePoints;
      document.getElementById('points-spent').textContent = `(已分配: ${totalPointsSpent})`;

      // 更新按钮状态
      updateButtonStates();

      // 生成命令文本
      let commandText = `${getAttributeLabel(attributeType)}分配属性点+1，`;

      // 添加到文本框
      let textarea = document.getElementById('command-text');
      textarea.value += commandText;
      textarea.scrollTop = textarea.scrollHeight; // 滚动到底部
    }

    // 获取属性标签
    function getAttributeLabel(attributeType) {
      const labels = {
        'constitution': '体质',
        'will': '意',
        'ac': 'AC',
        'agility': '敏捷'
      };
      return labels[attributeType] || attributeType;
    }

    // 更新按钮状态
    function updateButtonStates() {
      let availablePoints = parseInt(document.getElementById('attribute-points').textContent);
      document.querySelectorAll('.attr-btn').forEach(btn => {
        if (availablePoints <= 0) {
          btn.classList.add('disabled');
          btn.disabled = true;
        } else {
          btn.classList.remove('disabled');
          btn.disabled = false;
        }
      });
    }

    // 复制到剪贴板
    function copyToClipboard() {
      let textarea = document.getElementById('command-text');
      if (!textarea.value) {
        alert('没有可复制的内容！');
        return;
      }

      textarea.select();
      document.execCommand('copy');

      // 显示复制成功提示
      let originalValue = textarea.value;
      textarea.value = '已复制!';
      setTimeout(() => {
        textarea.value = originalValue;
      }, 1000);
    }

    // 统计命令
    function summarizeCommands() {
      let textarea = document.getElementById('command-text');
      let currentText = textarea.value.trim();

      if (!currentText) {
        alert('没有可统计的内容！');
        return;
      }

      const commands = currentText.split('，')
                                .map(cmd => cmd.trim())
                                .filter(cmd => cmd.length > 0);

      if (commands.length === 0) {
        alert('没有有效的命令可统计！');
        return;
      }

      const summary = {};
      const commandRegex = /^(体质|意|AC|敏捷)分配属性点\+(\d+)$/;
      let foundValidCommands = false;

      for (const command of commands) {
        const match = command.match(commandRegex);
        if (match) {
          const attributeName = match[1]; 
          const points = parseInt(match[2]); 
          summary[attributeName] = (summary[attributeName] || 0) + points;
          foundValidCommands = true;
        }
      }

      if (!foundValidCommands) {
        alert('未找到可统计的属性分配命令！原始文本将保留。');
        return; 
      }

      let newCommandTextParts = [];
      const attributeOrder = ['体质', '意', 'AC', '敏捷']; 

      for (const attr of attributeOrder) {
          if (summary.hasOwnProperty(attr) && summary[attr] > 0) {
              newCommandTextParts.push(`${attr}分配属性点+${summary[attr]}`);
          }
      }
      for (const attributeName in summary) {
          if (summary.hasOwnProperty(attributeName) && summary[attributeName] > 0 && !attributeOrder.includes(attributeName)) {
              newCommandTextParts.push(`${attributeName}分配属性点+${summary[attributeName]}`);
          }
      }

      let finalSummarizedText = newCommandTextParts.join('，');
      if (finalSummarizedText) { // Add trailing comma if there's content
          finalSummarizedText += '，';
      }

      textarea.value = '已统计!';
      setTimeout(() => {
        textarea.value = finalSummarizedText;
      }, 1000);
    }

    // 重置所有点数
    function resetAllPoints() {
      if (totalPointsSpent <= 0) {
        alert('没有已分配的点数可返还！');
        return;
      }

      if (!confirm('确定要清空所有已分配的属性点并返还点数吗？')) {
        return;
      }

      document.getElementById('command-text').value = '';

      let pointsElement = document.getElementById('attribute-points');
      pointsElement.textContent = initialPointsAvailable; // Reset to the very initial number of points

      for (let attrType in attributeIncrements) {
        if (originalValues.hasOwnProperty(attrType)) { // Check if it's a tracked attribute
          let valueElement = document.getElementById(attrType + '-value');
          valueElement.textContent = originalValues[attrType]; 
          attributeIncrements[attrType] = 0;
          document.getElementById(attrType + '-increment').textContent = '(+0)';
        }
      }

      totalPointsSpent = 0;
      document.getElementById('points-spent').textContent = '(已分配: 0)';
      updateButtonStates();
      alert('已清空所有分配并返还点数！');
    }

    // 页面加载时初始化
    document.addEventListener('DOMContentLoaded', function() {
      document.querySelectorAll('.attr-value').forEach(element => {
        let id = element.id;
        let attrType = id.replace('-value', '');
        if (['constitution', 'will', 'ac', 'agility'].includes(attrType)) { 
            originalValues[attrType] = parseInt(element.textContent);
        }
      });

      let pointsElem = document.getElementById('attribute-points');
      if (pointsElem) { 
        initialPointsAvailable = parseInt(pointsElem.textContent);
      }

      updateButtonStates();
      showTab('basic'); 
    });
  </script>
</details>
</body>
</html>
