class BattleSystem {
    static BATTLE_ATTRIBUTES = {
        YI: "意",       // 决定攻击的基础伤害值和暴击额外伤害
        AC: "AC",       // 降低被攻击命中的几率
        CONSTITUTION: "体质",  // 决定最大生命值，1点=20点生命值，默认基础50
        AGILITY: "敏捷"  // 加算到攻击投骰上，影响命中判定
    };

    constructor(gameDataManager) {
        this.gameDataManager = gameDataManager;
    }

    // 生成D20随机数
    rollD20() {
        return Math.floor(Math.random() * 20) + 1; // 1-20
    }

    // 生成指定面数的骰子结果
    rollDice(sides) {
        return Math.floor(Math.random() * sides) + 1; // 1-sides
    }

    // 执行攻击判定
    async performAttack(attackerYi, attackerAgility, defenderAC, skillDamage, defenderHP, skillDescription = "", attacker = "{{user}}", defender = "敌人", specialEffect = "") {
        // 投掷D20判定命中
        const d20Roll = this.rollD20();
        let hitResult = "";
        let damage = 0;
        let isCritical = false;
        let finalHitValue = 0;

        // 判断是否完美命中(D20=20)
        if (d20Roll === 20) {
            hitResult = "完美命中！无视AC直接命中并造成暴击！";
            isCritical = true;
        } else {
            // 计算综合命中值
            finalHitValue = d20Roll + attackerAgility - defenderAC;

            // 判断是否命中(最终命中值>=10)
            if (finalHitValue >= 10) {
                hitResult = "命中！";
            } else {
                hitResult = "未命中！";
            }
        }

        // 只有命中时才计算伤害
        let damageCalculation = "";
        let remainingHP = defenderHP;

        if (hitResult.includes("命中")) {
            // 基础伤害 = 攻击方"意"属性值 + 技能/武器伤害
            damage = attackerYi + skillDamage;
            damageCalculation = `${attackerYi} (意) + ${skillDamage} (技能/武器伤害)`;

            // 如果是暴击，额外增加1D[攻击方当前的"意"值]的伤害
            if (isCritical) {
                const critDamage = this.rollDice(attackerYi);
                damage += critDamage;
                damageCalculation += ` + ${critDamage} (暴击伤害，1D${attackerYi})`;
            }

            // 计算剩余生命值
            remainingHP = Math.max(0, defenderHP - damage);
            damageCalculation += ` = ${damage}点`;
        }

        // 构建技能效果描述
        let effectText = "";
        if (specialEffect && hitResult.includes("命中")) {
            effectText = `触发【${specialEffect}】效果。`;
        }

        // 构建生命值变化描述
        let hpChangeText = "";
        if (hitResult.includes("命中")) {
            hpChangeText = `${defender}当前生命值：${defenderHP}，${defenderHP} - ${damage} = ${remainingHP}。`;
        }

        // 根据不同情况构建最终输出
        let resultText = "";

        if (d20Roll === 20) {
            resultText = `攻击命中：1D20掷出${d20Roll}！${hitResult}${damageCalculation ? "伤害：" + damageCalculation : ""}。${effectText}${hpChangeText}`;
        } else if (hitResult.includes("命中")) {
            resultText = `攻击命中：1D20掷出${d20Roll}。最终命中值：${d20Roll} (骰值) + ${attackerAgility} (攻击方敏捷) - ${defenderAC} (防御方AC) = ${finalHitValue}。${finalHitValue} ≥ 10，${hitResult}${damageCalculation ? "伤害：" + damageCalculation : ""}。${effectText}${hpChangeText}`;
        } else {
            resultText = `攻击命中：1D20掷出${d20Roll}。最终命中值：${d20Roll} (骰值) + ${attackerAgility} (攻击方敏捷) - ${defenderAC} (防御方AC) = ${finalHitValue}。${finalHitValue} < 10，${hitResult}`;
        }

        return {
            d20Roll: d20Roll,
            hitResult: hitResult,
            damage: damage,
            isCritical: isCritical,
            finalHitValue: finalHitValue,
            remainingHP: remainingHP,
            resultText: resultText,
            attacker: attacker,
            defender: defender,
            skillDescription: skillDescription
        };
    }

    // 输出攻击结果到AI
    async outputAttackResult(result) {
        const message = `<投骰>${result.resultText}</投骰>`;
        await triggerSlash(`/send ${message}`);
    }
}

class BattleSystemUI {
    constructor() {
        this.battleSystem = new BattleSystem(window.gameDataManager);
        this.createUI();
        this.bindEvents();
    }

    createUI() {
        // 创建主对话框
        const battleDialog = document.createElement('div');
        battleDialog.className = 'battle-dialog';
        battleDialog.style.cssText = 'display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0,0,0,0.7); z-index: 1000; justify-content: center; align-items: center;';

        // 创建对话框内容
        const dialogContent = document.createElement('div');
        dialogContent.className = 'battle-dialog-content';
        dialogContent.style.cssText = 'background-color: #1a1a2e; border: 2px solid #a27dff; border-radius: 10px; padding: 20px; width: 90%; max-width: 500px; color: #e0e0e0; position: relative;';

        // 关闭按钮
        const closeButton = document.createElement('button');
        closeButton.innerHTML = '&times;';
        closeButton.style.cssText = 'position: absolute; top: 10px; right: 15px; background: none; border: none; font-size: 24px; color: #a27dff; cursor: pointer;';
        closeButton.className = 'battle-close';

        // 标题
        const title = document.createElement('h3');
        title.textContent = '战斗判定系统';
        title.style.cssText = 'color: #a27dff; text-align: center; margin-bottom: 20px;';

        // 表单创建
        dialogContent.innerHTML += `
            <div style="margin-bottom: 15px;">
                <label for="attacker-name" style="display: block; margin-bottom: 5px;">攻击者名称:</label>
                <input type="text" id="attacker-name" value="{{user}}" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;">
            </div>

            <div style="margin-bottom: 15px;">
                <label for="defender-name" style="display: block; margin-bottom: 5px;">防御者名称:</label>
                <input type="text" id="defender-name" value="敌人" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;">
            </div>

            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 15px;">
                <div>
                    <label for="attacker-yi" style="display: block; margin-bottom: 5px;">攻击者意:</label>
                    <input type="number" id="attacker-yi" value="3" min="0" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;">
                </div>
                <div>
                    <label for="attacker-agility" style="display: block; margin-bottom: 5px;">攻击者敏捷:</label>
                    <input type="number" id="attacker-agility" value="2" min="0" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;">
                </div>
            </div>

            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 15px;">
                <div>
                    <label for="defender-ac" style="display: block; margin-bottom: 5px;">防御者AC:</label>
                    <input type="number" id="defender-ac" value="1" min="0" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;">
                </div>
                <div>
                    <label for="defender-hp" style="display: block; margin-bottom: 5px;">防御者当前HP:</label>
                    <input type="number" id="defender-hp" value="60" min="0" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;">
                </div>
            </div>

            <div style="margin-bottom: 15px;">
                <label for="skill-damage" style="display: block; margin-bottom: 5px;">技能/武器伤害值:</label>
                <input type="number" id="skill-damage" value="0" min="0" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;">
            </div>

            <div style="margin-bottom: 15px;">
                <label for="special-effect" style="display: block; margin-bottom: 5px;">特殊效果(可选):</label>
                <input type="text" id="special-effect" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0;" placeholder="例如: 灼伤、击退">
            </div>

            <div style="margin-bottom: 15px;">
                <label for="skill-description" style="display: block; margin-bottom: 5px;">技能描述(可选):</label>
                <textarea id="skill-description" style="width: 100%; padding: 8px; background-color: #2d2d42; border: 1px solid #a27dff; border-radius: 5px; color: #e0e0e0; height: 80px; resize: vertical;" placeholder="技能的具体描述"></textarea>
            </div>

            <div style="text-align: center; margin-top: 20px;">
                <button id="perform-attack" style="background: linear-gradient(135deg, #6e48aa, #9d50bb); color: white; border: none; padding: 10px 20px; border-radius: 5px; cursor: pointer; font-size: 16px; transition: transform 0.2s;">执行攻击判定</button>
            </div>
        `;

        // 添加结果对话框
        const resultDialog = document.createElement('div');
        resultDialog.className = 'battle-result-dialog';
        resultDialog.style.cssText = 'display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0,0,0,0.7); z-index: 1000; justify-content: center; align-items: center;';

        const resultContent = document.createElement('div');
        resultContent.className = 'battle-result-content';
        resultContent.style.cssText = 'background-color: #1a1a2e; border: 2px solid #a27dff; border-radius: 10px; padding: 20px; width: 90%; max-width: 500px; color: #e0e0e0; position: relative;';

        resultContent.innerHTML = `
            <button class="result-close" style="position: absolute; top: 10px; right: 15px; background: none; border: none; font-size: 24px; color: #a27dff; cursor: pointer;">&times;</button>
            <h3 style="color: #a27dff; text-align: center; margin-bottom: 20px;">攻击结果</h3>

            <div id="battle-dice-result" style="background-color: #2d2d42; padding: 15px; border-radius: 8px; margin-bottom: 15px; white-space: pre-wrap; word-break: break-word;"></div>

            <div style="text-align: center; margin-top: 20px;">
                <button id="send-result" style="background: linear-gradient(135deg, #6e48aa, #9d50bb); color: white; border: none; padding: 10px 20px; border-radius: 5px; cursor: pointer; font-size: 16px; transition: transform 0.2s;">发送结果</button>
            </div>
        `;

        // 组合所有元素
        dialogContent.appendChild(closeButton);
        battleDialog.appendChild(dialogContent);
        resultDialog.appendChild(resultContent);

        // 添加到文档
        document.body.appendChild(battleDialog);
        document.body.appendChild(resultDialog);

        // 保存引用
        this.battleDialog = battleDialog;
        this.resultDialog = resultDialog;
        this.battleDiceResult = resultContent.querySelector('#battle-dice-result');
    }

    bindEvents() {
        // 创建触发按钮
        const triggerButton = document.createElement('button');
        triggerButton.textContent = '战斗判定';
        triggerButton.style.cssText = 'background: linear-gradient(135deg, #6e48aa, #9d50bb); color: white; border: none; padding: 8px 15px; border-radius: 5px; cursor: pointer; margin: 5px; font-size: 14px;';

        // 将按钮添加到SillyTavern的某个位置
        const insertButton = () => {
            // 尝试找到SillyTavern的工具栏或者其他适合的位置
            const toolbarContainer = document.querySelector('#send_form, #chat-controls, #chat_toolbar');
            if (toolbarContainer) {
                toolbarContainer.appendChild(triggerButton);
                return true;
            }
            return false;
        };

        // 如果页面已经加载完成
        if (document.readyState === 'complete') {
            insertButton();
        } else {
            // 如果页面正在加载，等待加载完成
            window.addEventListener('load', function() {
                // 如果不能立即添加，尝试几次
                let attempts = 0;
                const interval = setInterval(() => {
                    if (insertButton() || attempts > 10) {
                        clearInterval(interval);
                    }
                    attempts++;
                }, 500);
            });
        }

        // 点击触发按钮显示战斗判定对话框
        triggerButton.addEventListener('click', () => {
            this.battleDialog.style.display = 'flex';
        });

        // 关闭战斗判定对话框
        this.battleDialog.querySelector('.battle-close').addEventListener('click', () => {
            this.battleDialog.style.display = 'none';
        });

        // 执行攻击判定
        document.getElementById('perform-attack').addEventListener('click', async () => {
            const attackerName = document.getElementById('attacker-name').value;
            const defenderName = document.getElementById('defender-name').value;
            const attackerYi = parseInt(document.getElementById('attacker-yi').value) || 0;
            const attackerAgility = parseInt(document.getElementById('attacker-agility').value) || 0;
            const defenderAC = parseInt(document.getElementById('defender-ac').value) || 0;
            const defenderHP = parseInt(document.getElementById('defender-hp').value) || 0;
            const skillDamage = parseInt(document.getElementById('skill-damage').value) || 0;
            const specialEffect = document.getElementById('special-effect').value;
            const skillDescription = document.getElementById('skill-description').value;

            const result = await this.battleSystem.performAttack(
                attackerYi,
                attackerAgility,
                defenderAC,
                skillDamage,
                defenderHP,
                skillDescription,
                attackerName,
                defenderName,
                specialEffect
            );

            // 保存当前结果
            this.currentResult = result;

            // 显示结果
            this.battleDiceResult.textContent = result.resultText;
            this.battleDialog.style.display = 'none';
            this.resultDialog.style.display = 'flex';
        });

        // 关闭结果对话框
        this.resultDialog.querySelector('.result-close').addEventListener('click', () => {
            this.resultDialog.style.display = 'none';
        });

        // 发送结果
        document.getElementById('send-result').addEventListener('click', async () => {
            if (this.currentResult) {
                await this.battleSystem.outputAttackResult(this.currentResult);
                this.resultDialog.style.display = 'none';
            }
        });
    }
}

// 初始化
window.battleSystemUI = new BattleSystemUI();
